            int bsum = 0;

            for (int ib = 0; ib < 8; ib++)
            {
                byte scaleByte = block[74 + ib]; // one byte carries the sub-block's two scale codes
                uint signs = StageIQ2SMagnitudes(block + 2 + 4 * ib, block[66 + ib], block + 34 + 4 * ib, mag);

                int lo;
                int hi;

                fixed (byte* pMag = mag)
                {
                    SubBlockDotQ8KVector(pMag, signs, (sbyte*)(qa + bi * QkK + ib * 32), out lo, out hi, dot);
                }

                bsum += (1 + 2 * (scaleByte & 0xF)) * lo; // ls1 over groups 0..1 and ls2 over groups 2..3, as in the scalar path
                bsum += (1 + 2 * (scaleByte >> 4)) * hi;
            }

            sumf += d * bsum;
        }

        return 0.125f * sumf;
    }

    // Stage one IQ2_S sub-block: each group's nine-bit grid index combines its qs byte with bits 2l and 2l+1 of the
    // sub-block's qh byte at bits 8 and 9, the referenced entry is read as one unaligned ulong in element order, and
    // the group's sign byte comes straight from the sign plane the reference reaches through qs + QK_K/8 - raw sign
    // bytes rather than a ksigns table lookup. Identical staging for both dot paths and every vector of a batch.
    private static uint StageIQ2SMagnitudes(byte* qs, byte qh, byte* signs, Span<byte> mag)
    {
        fixed (byte* pGrid = GetIq2SGrid())
        fixed (byte* pMag = mag)
        {
            uint packed = 0;

            for (int l = 0; l < 4; l++)
            {
                int gi = qs[l] | (((qh >> (2 * l)) & 1) << 8) | (((qh >> (2 * l + 1)) & 1) << 9); // nine-bit grid index
                Unsafe.WriteUnaligned(pMag + 8 * l, Unsafe.ReadUnaligned<ulong>(pGrid + (nint)gi * 8));
                packed |= (uint)signs[l] << (8 * l);
            }

            return packed;
        }
    }

    // IQ2_S sub-block staging: for each of the four eight-value groups, take the group's sign byte from the sign
    // plane the reference reaches through qs + QK_K/8, gather the referenced grid entry's eight magnitude bytes into
    // one broadcast vector (byte lanes 0..7 in element order), widen them with sign (pmovsxbd) so every byte lands
    // as its exact integer value, multiply by the group's sub-block scale, and flip the selected lanes by XOR-ing
    // the float sign bit (exact for every finite value, matching the reference multiply by -1.f). The staged weights
    // land in element order so the fused chunks match the scalar oracle.
    private static void FillIQ2SSubBlock(byte* qs, byte qh, byte* signs, float dbLo, float dbHi, Span<float> stage)
    {
        fixed (float* pStage = stage)
        {
            ReadOnlySpan<byte> gridTable = GetIq2SGrid();

            for (int l = 0; l < 4; l++)
            {
                byte sign = signs[l];

                // Nine-bit grid index: the qs byte plus bits 2l and 2l+1 of the qh byte at bits 8 and 9.
                int gi = qs[l] | (((qh >> (2 * l)) & 1) << 8) | (((qh >> (2 * l + 1)) & 1) << 9);

                // Eight magnitude bytes of the referenced entry, combined little-endian into one broadcast vector.
                int off = gi * 8;
                ulong low = (uint)(gridTable[off] | (gridTable[off + 1] << 8) | (gridTable[off + 2] << 16) | (gridTable[off + 3] << 24));
                ulong high = (uint)(gridTable[off + 4] | (gridTable[off + 5] << 8) | (gridTable[off + 6] << 16) | (gridTable[off + 7] << 24));
                Vector128<sbyte> magnitudes = Vector128.Create(low | (high << 32)).AsSByte();
                Vector128<int> magLo = Sse41.ConvertToVector128Int32(magnitudes); // bytes 0..3 -> dword lanes (pmovsxbd, magnitudes all < 128)
                Vector128<int> magHi = Sse41.ConvertToVector128Int32(Ssse3.Shuffle(magnitudes.AsByte(), GetUpperBytesShuffle()).AsSByte()); // bytes 4..7 -> dword lanes

                float dbLocal = l < 2 ? dbLo : dbHi;
                Vector128<float> dbV = Avx.BroadcastScalarToVector128(&dbLocal);
                Vector128<float> wLo = Sse.Multiply(Avx.ConvertToVector128Single(magLo), dbV); // cvtdq2ps then scale
                Vector128<float> wHi = Sse.Multiply(Avx.ConvertToVector128Single(magHi), dbV);

                Sse.Store(pStage + l * 8, Avx2.Xor(wLo.AsInt32(), SignMaskIQ2XS(sign, 0)).AsSingle());
                Sse.Store(pStage + l * 8 + 4, Avx2.Xor(wHi.AsInt32(), SignMaskIQ2XS(sign, 4)).AsSingle());
            }
        }
    }

    // Batched IQ2_S row: one staged sub-block feeds every vector's integer dot in RowDotIQ2SQ8Vector's integer and float
    // order, so the packed bytes are streamed once for the whole batch. Each vector keeps its own exact int32 super-block total.
    private static void BatchIQ2SQ8_Vector(byte* row, byte* qa, float* da, int blocks, int count, int rows, float* outBase, IntegerDotPath dot)
    {
        Span<byte> mag = stackalloc byte[32]; // magnitude bytes of the current 32-value sub-block
        Span<int> bsum = stackalloc int[MaxBatch]; // exact per-vector integer super-block totals
        Span<float> sumf = stackalloc float[MaxBatch];

        for (int bi = 0; bi < blocks; bi++)
        {
            byte* block = row + (long)bi * IQ2SBlockBytes;
            float dw = ReadHalfLE(block); // half-float weight scale, multiplied by each vector's activation scale in the reference order

            for (int ib = 0; ib < 8; ib++)
            {
                byte scaleByte = block[74 + ib]; // one byte carries the sub-block's two scale codes
                int ls1 = 1 + 2 * (scaleByte & 0xF);
                int ls2 = 1 + 2 * (scaleByte >> 4);

                uint signs = StageIQ2SMagnitudes(block + 2 + 4 * ib, block[66 + ib], block + 34 + 4 * ib, mag); // decoded once per sub-block and reused across the batch

                fixed (byte* pMag = mag)
                {
                    for (int b = 0; b < count; b++)
                    {
                        SubBlockDotQ8KVector(pMag, signs, (sbyte*)(qa + (long)b * blocks * QkK + bi * QkK + ib * 32), out int lo, out int hi, dot);
                        bsum[b] += ls1 * lo;
                        bsum[b] += ls2 * hi;
                    }
                }
            }

            for (int b = 0; b < count; b++)
            {
                sumf[b] += (dw * da[(long)b * blocks + bi]) * bsum[b]; // same float grouping as the single-vector kernel
                bsum[b] = 0;
            }
        }

        for (int b = 0; b < count; b++)
        {
            outBase[(long)b * rows] = 0.125f * sumf[b]; // the reference's single final factor, applied exactly as in RowDotIQ2SQ8Vector
        }
    }

    // IQ2_S row expansion: w = db * grid byte, sign-applied through the sign plane the reference reaches through
    // qs + QK_K/8, per element. Same grid/sign staging as RowDotIQ2SAvx2, storing the staged weights instead of
    // dotting them.
    private static void DequantIQ2SAvx2(byte* row, float* outPtr, int cols)
    {
        Span<float> stage = stackalloc float[32]; // staging buffer for the current 32-value sub-block

        for (int baseIdx = 0; baseIdx < cols; baseIdx += QkK)
        {
            byte* block = row + (long)(baseIdx / QkK) * IQ2SBlockBytes;
            float dHalf = ReadHalfLE(block);

            for (int ib = 0; ib < 8; ib++)
            {
                int subStart = baseIdx + ib * 32;
                if (subStart >= cols)
                {
                    break; // zero-padded tail block: no elements left to consume.
                }

                float dbLo = dHalf * (0.5f + (block[74 + ib] & 0xF)) * 0.25f;
                float dbHi = dHalf * (0.5f + (block[74 + ib] >> 4)) * 0.25f;
                int limit = Math.Min(32, cols - subStart); // padded quants are zero: stop at the real column count.

                FillIQ2SSubBlock(block + 2 + 4 * ib, block[66 + ib], block + 34 + 4 * ib, dbLo, dbHi, stage);

                fixed (float* pStage = stage)
                {
                    for (int c = 0; c + 8 <= limit; c += 8)
                    {
                        Avx.Store(outPtr + subStart + c, Avx.LoadVector256(pStage + c)); // staged weights, materialized once per sub-block
                    }
                }

                for (int l = (limit / 8) * 8; l < limit; l++)
                {
                    outPtr[subStart + l] = stage[l]; // partial final chunk: at most seven elements per sub-block
                }
            }
        }
    }
}
